head.script:
//
tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      fontFamily: {
        cyber: ['Orbitron', 'sans-serif'],
        space: ['Space Grotesk', 'sans-serif'],
        mono: ['JetBrains Mono', 'monospace'],
        tech: ['Rajdhani', 'sans-serif'],
      }
    }
  }
};
//

head.b:skin:
    .navbar, #navbar, .widget-item-control, .quickedit, .status-msg-wrap { display: none !important; }

    html, body {
      margin: 0;
      padding: 0;
      background-color: #040609 !important;
      color: #e2e8f0;
      font-family: 'Space Grotesk', system-ui, sans-serif;
      overflow-x: hidden;
    }



@layer base {
  :root {
    --font-orbitron: 'Orbitron', system-ui, sans-serif;
    --font-space: 'Space Grotesk', system-ui, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
    --font-rajdhani: 'Rajdhani', sans-serif;
  }

  body {
    font-family: var(--font-space);
    background-color: #040609;
    color: #e2e8f0;
  }

  h1, h2, h3, .font-cyber {
    font-family: var(--font-orbitron);
  }

  .font-tech {
    font-family: var(--font-rajdhani);
  }

  code, pre, .font-terminal {
    font-family: var(--font-mono);
  }
}

/* Custom Cyber Glows & Glassmorphism */
.glass-panel {
  background: rgba(8, 14, 26, 0.65);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 240, 255, 0.15);
}

.glass-panel-crimson {
  background: rgba(20, 6, 12, 0.65);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 0, 85, 0.25);
}

.glass-card-hover {
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.glass-card-hover:hover {
  transform: translateY(-4px);
  border-color: rgba(0, 240, 255, 0.45);
  box-shadow: 0 10px 30px -10px rgba(0, 240, 255, 0.25), 0 0 1px 1px rgba(0, 240, 255, 0.3);
}

.neon-border-cyan {
  border-color: rgba(0, 240, 255, 0.4);
  box-shadow: 0 0 15px rgba(0, 240, 255, 0.25), inset 0 0 15px rgba(0, 240, 255, 0.1);
}

.neon-border-crimson {
  border-color: rgba(255, 0, 85, 0.5);
  box-shadow: 0 0 15px rgba(255, 0, 85, 0.3), inset 0 0 15px rgba(255, 0, 85, 0.1);
}

.cyber-grid {
  background-size: 40px 40px;
  background-image: 
    linear-gradient(to right, rgba(0, 240, 255, 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 240, 255, 0.04) 1px, transparent 1px);
}

.cyber-dots {
  background-image: radial-gradient(rgba(0, 240, 255, 0.15) 1px, transparent 1px);
  background-size: 24px 24px;
}

.scanlines {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%, 
    rgba(0, 0, 0, 0.25) 50%
  ), linear-gradient(
    90deg,
    rgba(255, 0, 0, 0.03),
    rgba(0, 255, 0, 0.01),
    rgba(0, 0, 255, 0.03)
  );
  background-size: 100% 3px, 6px 100%;
}

@keyframes scan {
  0% {
    top: 0%;
    opacity: 0.8;
  }
  50% {
    top: 96%;
    opacity: 1;
  }
  100% {
    top: 0%;
    opacity: 0.8;
  }
}

.animate-scan {
  animation: scan 2.5s ease-in-out infinite;
}

@keyframes pulseGlow {
  0%, 100% {
    opacity: 0.6;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.03);
  }
}

@keyframes radarSweep {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

.animate-pulse-glow {
  animation: pulseGlow 4s ease-in-out infinite;
}

.animate-radar {
  animation: radarSweep 8s linear infinite;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #040609;
}

::-webkit-scrollbar-thumb {
  background: #152238;
  border-radius: 4px;
  border: 1px solid rgba(0, 240, 255, 0.2);
}

::-webkit-scrollbar-thumb:hover {
  background: #00f0ff88;
}

